class RetailerOrderItem {
  constructor(
    id,
    draft_id,
    unit_of_issue,
    product_id,
    product_title,
    units_per_pack,
    pack_selling_price,
    batch,
    wholesaler_receipt,
    pack_quantity,
    required_quantity,
    discount_quantity,
    total_quantity,
    item_price,
    discount_amount,
    tax_amount,
    net_price,
    total_amount,
    image
  ) {
    this.id = id;
    this.draft_id = draft_id;
    this.unit_of_issue = unit_of_issue;
    this.product_id = product_id;
    this.product_title = product_title;
    this.units_per_pack = units_per_pack;
    this.pack_selling_price = pack_selling_price;
    this.batch = batch;
    this.wholesaler_receipt = wholesaler_receipt;
    this.pack_quantity = pack_quantity;
    this.required_quantity = required_quantity;
    this.discount_quantity = discount_quantity;
    this.total_quantity = total_quantity;
    this.item_price = item_price;
    this.discount_amount = discount_amount;
    this.tax_amount = tax_amount;
    this.net_price = net_price;
    this.total_amount = total_amount;
    this.image = image;
  }
}

export default RetailerOrderItem;
