import React, { useState } from "react";
import { Button, Modal, Space } from "antd";
export default function ConfirmDialog({
  open,
  setOpen,
  handleOkSelected,
  selectedEmployee,
}) {
  const handleOk = () => {
    handleOkSelected();
    setOpen(false);
  };
  const handleCancel = () => {
    setOpen(false);
  };
  return (
    <div>
      <Modal
        open={open}
        title={
          selectedEmployee ? selectedEmployee.title : "No employee selected"
        }
        onOk={handleOk}
        onCancel={handleCancel}
        footer={(_, { OkBtn, CancelBtn }) => (
          <>
            <CancelBtn />
            <OkBtn />
          </>
        )}
      >
        <p>
          You are about to make {selectedEmployee.title} and Administrator of{" "}
          {selectedEmployee.entity_title}
        </p>
        <p>
          {selectedEmployee.title} will be able to directly administer all
          entity inventory, users and collections
        </p>
      </Modal>
    </div>
  );
}
