import React from 'react'
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Input, Link } from "@heroui/react";
function YesNoModal({ header, title, content, showModal, setShowModal, yesAction, yesActionLabel = "Ok", noAction, noActionLabel = "Cancel" }) {

    return (
      <Modal isOpen={showModal} placement="center" backdrop="opaque">
        <ModalContent>
          {() => (
            <>
              <ModalHeader
                about="dhhdh"
                className="flex flex-col gap-1 items-center justify-center rounded-sm"
              >
                {title}
              </ModalHeader>

              <ModalBody className="items-center justify-center">
                <h1>{content}</h1>
              </ModalBody>
              <ModalFooter className="w-full items-center justify-between">
                <Button
                  color="danger"
                  variant="flat"
                  onPress={() => setShowModal(false)}
                >
                  {noActionLabel}
                </Button>
                <Button color="primary" onPress={() => yesAction()}>
                  {yesActionLabel}
                </Button>
              </ModalFooter>
            </>
          )}
        </ModalContent>
      </Modal>
    );
}

export default YesNoModal